import time
from dataclasses import dataclass, field

import numpy as np

from src.config import MandelbrotConfig
from src.mb_calculator import MandelbrotCalculator
from benchmark_config import BenchmarkConfig


@dataclass
class BenchmarkResult:
    calculator_name: str
    resolution: int
    times: list[float] = field(default_factory=list)

    @property
    def mean_time(self) -> float:
        return float(np.mean(self.times))

    @property
    def std_time(self) -> float:
        return float(np.std(self.times))

    @property
    def min_time(self) -> float:
        return float(np.min(self.times))


class BenchmarkRunner:
    """Runs benchmarks for configured calculators across resolution ramp-up."""

    def __init__(self, config: BenchmarkConfig):
        self.config = config
        self.results: list[BenchmarkResult] = []

    def run(self) -> list[BenchmarkResult]:
        """Execute the full benchmark suite."""
        self.results = []
        calculator_classes = self.config.get_calculator_classes()

        for calc_cls in calculator_classes:
            for res in self.config.resolutions:
                result = self._benchmark_single(calc_cls, res)
                self.results.append(result)
                print(f"  {result.calculator_name} @ {res}x{res}: "
                      f"{result.mean_time:.4f}s (±{result.std_time:.4f}s)")

        return self.results

    def _benchmark_single(self, calc_cls: type[MandelbrotCalculator], resolution: int) -> BenchmarkResult:
        """Benchmark a single calculator at a specific resolution."""
        mb_cfg = MandelbrotConfig(
            xmin=self.config.mb_config.xmin,
            xmax=self.config.mb_config.xmax,
            ymin=self.config.mb_config.ymin,
            ymax=self.config.mb_config.ymax,
            width=resolution,
            height=resolution,
            max_iter=self.config.mb_config.max_iter,
            chunk_size=self.config.mb_config.chunk_size,
            num_processes=self.config.mb_config.num_processes,
        )

        calculator = calc_cls(mb_cfg)
        result = BenchmarkResult(calculator_name=calc_cls.__name__, resolution=resolution)

        # Warmup
        for _ in range(self.config.warmup_runs):
            calculator.calculate()

        # Timed runs
        for _ in range(self.config.num_runs):
            start = time.perf_counter()
            calculator.calculate()
            elapsed = time.perf_counter() - start
            result.times.append(elapsed)

        return result
